insert into public.gallery_photos (id, album_id, src, alt, width, height, position) values
  ('grup-scena', 'concert-5-ani', 'concert-5-ani/grup-scena', '{"ro":"Tot corul și bandul pe scenă, sub numele Harmonia Christi proiectat în spate","en":"The whole choir and band on stage, with the name Harmonia Christi projected behind them","it":"Tutto il coro e la band sul palco, con il nome Harmonia Christi proiettato alle spalle","de":"Der ganze Chor und die Band auf der Bühne, dahinter der projizierte Name Harmonia Christi"}'::jsonb, null, null, 0),
  ('voci-si-band', 'concert-5-ani', 'concert-5-ani/voci-si-band', '{"ro":"Fetele în galben și băieții în verde cântă, cu bandul în față","en":"Girls in yellow and boys in green singing, with the band in front","it":"Le ragazze in giallo e i ragazzi in verde cantano, con la band davanti","de":"Mädchen in Gelb und Jungen in Grün singen, davor die Band"}'::jsonb, null, null, 1),
  ('alelia-dirijat', 'concert-5-ani', 'concert-5-ani/alelia-dirijat', '{"ro":"Corul dirijat în fața ecranului pe care scrie Aleluia","en":"The choir being conducted in front of a screen reading Alleluia","it":"Il coro diretto davanti allo schermo con la scritta Alleluia","de":"Der Chor wird vor der Leinwand mit dem Schriftzug Halleluja dirigiert"}'::jsonb, null, null, 2),
  ('baieti-grup', 'concert-5-ani', 'concert-5-ani/baieti-grup', '{"ro":"Vocile bărbătești, în tricouri verzi cu inimă albă","en":"The men''s voices, in green T-shirts with a white heart","it":"Le voci maschili, in maglietta verde con un cuore bianco","de":"Die Männerstimmen in grünen T-Shirts mit weißem Herzen"}'::jsonb, null, null, 3),
  ('grup-aplauze', 'concert-5-ani', 'concert-5-ani/grup-aplauze', '{"ro":"Corul pe scenă, la finalul concertului","en":"The choir on stage at the end of the concert","it":"Il coro sul palco alla fine del concerto","de":"Der Chor auf der Bühne am Ende des Konzerts"}'::jsonb, null, null, 4),
  ('baieti-cantand', 'concert-5-ani', 'concert-5-ani/baieti-cantand', '{"ro":"Băieții cântă strânși în jurul microfonului","en":"The boys sing, gathered round the microphone","it":"I ragazzi cantano stretti attorno al microfono","de":"Die Jungen singen dicht um das Mikrofon"}'::jsonb, null, null, 5),
  ('alelia-cor', 'concert-5-ani', 'concert-5-ani/alelia-cor', '{"ro":"Cor și instrumentiști sub proiecția Aleluia","en":"Choir and instrumentalists under the Alleluia projection","it":"Coro e strumentisti sotto la proiezione Alleluia","de":"Chor und Instrumentalisten unter der Halleluja-Projektion"}'::jsonb, null, null, 6),
  ('voci-si-band-2', 'concert-5-ani', 'concert-5-ani/voci-si-band-2', '{"ro":"Voci și instrumente într-un singur cânt","en":"Voices and instruments in a single song","it":"Voci e strumenti in un solo canto","de":"Stimmen und Instrumente in einem einzigen Lied"}'::jsonb, null, null, 7),
  ('sala-mare', 'concert-5-ani', 'concert-5-ani/sala-mare', '{"ro":"Cuvânt adresat publicului, cu tot corul în spate","en":"A word to the audience, with the whole choir behind","it":"Una parola al pubblico, con tutto il coro alle spalle","de":"Ein Wort an das Publikum, der ganze Chor dahinter"}'::jsonb, null, null, 8),
  ('italia-2026-grup-lac', 'italia-2026', 'italia-2026/grup-lac', '{"ro":"Toți împreună pe malul unui lac, cu munții în spate","en":"All of us together on a lakeshore, with mountains behind","it":"Tutti insieme sulla riva di un lago, con le montagne alle spalle","de":"Wir alle zusammen am Ufer eines Sees, dahinter die Berge"}'::jsonb, null, null, 0),
  ('italia-2026-cor-altar', 'italia-2026', 'italia-2026/cor-altar', '{"ro":"Corul în alb și galben, în fața altarului, la concert","en":"The choir in white and yellow before the altar, in concert","it":"Il coro in bianco e giallo davanti all''altare, durante il concerto","de":"Der Chor in Weiß und Gelb vor dem Altar, beim Konzert"}'::jsonb, null, null, 1),
  ('italia-2026-grup-panorama', 'italia-2026', 'italia-2026/grup-panorama', '{"ro":"Fotografie de grup deasupra unei văi, cu dealuri în zare","en":"Group photo above a valley, with hills on the horizon","it":"Foto di gruppo sopra una valle, con le colline all''orizzonte","de":"Gruppenfoto über einem Tal, am Horizont die Hügel"}'::jsonb, null, null, 2),
  ('italia-2026-voci-aproape', 'italia-2026', 'italia-2026/voci-aproape', '{"ro":"Cântăm strânși unii lângă alții, cu partiturile în mână","en":"Singing shoulder to shoulder, scores in hand","it":"Cantiamo stretti gli uni agli altri, con gli spartiti in mano","de":"Wir singen dicht beieinander, die Noten in der Hand"}'::jsonb, null, null, 3),
  ('italia-2026-grup-munti', 'italia-2026', 'italia-2026/grup-munti', '{"ro":"Grupul nostru în piață, sub munții înzăpeziți","en":"Our group in a square, beneath snowy mountains","it":"Il nostro gruppo in piazza, sotto le montagne innevate","de":"Unsere Gruppe auf einem Platz, unter verschneiten Bergen"}'::jsonb, null, null, 4),
  ('italia-2026-in-biserica', 'italia-2026', 'italia-2026/in-biserica', '{"ro":"Cântăm în biserică, în haine de zi, cu claviatura lângă noi","en":"Singing in church in everyday clothes, with the keyboard beside us","it":"Cantiamo in chiesa con gli abiti di tutti i giorni, accanto alla tastiera","de":"Wir singen in Alltagskleidung in der Kirche, neben uns das Keyboard"}'::jsonb, null, null, 5),
  ('italia-2026-supa', 'italia-2026', 'italia-2026/supa', '{"ro":"O soră ne împarte supa la bucătărie","en":"A sister serving us soup in the kitchen","it":"Una suora ci serve la minestra in cucina","de":"Eine Schwester teilt uns in der Küche die Suppe aus"}'::jsonb, null, null, 6),
  ('italia-2026-esarfe-galbene', 'italia-2026', 'italia-2026/esarfe-galbene', '{"ro":"Corul în alb și negru, cu eșarfe galbene, într-o piață de la munte","en":"The choir in black and white with yellow scarves, in a mountain square","it":"Il coro in bianco e nero con le sciarpe gialle, in una piazza di montagna","de":"Der Chor in Schwarz und Weiß mit gelben Tüchern auf einem Platz in den Bergen"}'::jsonb, null, null, 7),
  ('italia-2026-bratele-sus', 'italia-2026', 'italia-2026/bratele-sus', '{"ro":"Două coriste cântă cu brațele ridicate, în biserică","en":"Two singers with their arms raised, in church","it":"Due coriste cantano con le braccia alzate, in chiesa","de":"Zwei Sängerinnen mit erhobenen Armen in der Kirche"}'::jsonb, null, null, 8),
  ('italia-2026-aplauze', 'italia-2026', 'italia-2026/aplauze', '{"ro":"Cântăm și bătem din palme în sala de mese","en":"Singing and clapping in the dining hall","it":"Cantiamo e battiamo le mani in sala da pranzo","de":"Wir singen und klatschen im Speisesaal"}'::jsonb, null, null, 9),
  ('italia-2026-baieti-negru', 'italia-2026', 'italia-2026/baieti-negru', '{"ro":"Băieții corului în negru, gata să cânte","en":"The men of the choir in black, ready to sing","it":"I ragazzi del coro in nero, pronti a cantare","de":"Die Männer des Chors in Schwarz, bereit zum Singen"}'::jsonb, null, null, 10),
