  ('italia-2026-grup-altar', 'italia-2026', 'italia-2026/grup-altar', '{"ro":"Fotografie de grup în fața altarului, într-o biserică bogat împodobită","en":"Group photo before the altar of a richly decorated church","it":"Foto di gruppo davanti all''altare di una chiesa riccamente decorata","de":"Gruppenfoto vor dem Altar einer reich geschmückten Kirche"}'::jsonb, null, null, 13),
  ('italia-2026-servim', 'italia-2026', 'italia-2026/servim', '{"ro":"Băieții pun mâncarea în boluri pentru ceilalți","en":"The boys dishing up bowls for everyone else","it":"I ragazzi riempiono le ciotole per gli altri","de":"Die Jungen füllen die Schüsseln für die anderen"}'::jsonb, null, null, 14),
  ('italia-2026-patru-voci', 'italia-2026', 'italia-2026/patru-voci', '{"ro":"Patru voci bărbătești la același microfon","en":"Four men''s voices at the same microphone","it":"Quattro voci maschili allo stesso microfono","de":"Vier Männerstimmen am selben Mikrofon"}'::jsonb, null, null, 15),
  ('italia-2026-seara-impreuna', 'italia-2026', 'italia-2026/seara-impreuna', '{"ro":"Seară împreună în sala de mese","en":"An evening together in the dining hall","it":"Una serata insieme in sala da pranzo","de":"Ein gemeinsamer Abend im Speisesaal"}'::jsonb, null, null, 16),
  ('italia-2026-concert-din-banci', 'italia-2026', 'italia-2026/concert-din-banci', '{"ro":"Corul în fața altarului, văzut din bănci","en":"The choir before the altar, seen from the pews","it":"Il coro davanti all''altare, visto dai banchi","de":"Der Chor vor dem Altar, von den Bänken aus gesehen"}'::jsonb, null, null, 17),
