  ('italia-2026-veselie', 'italia-2026', 'italia-2026/veselie', '{"ro":"Râdem și ne ținem de mână, într-o seară împreună","en":"Laughing and holding hands on an evening together","it":"Ridiamo tenendoci per mano, in una serata insieme","de":"Wir lachen und halten uns an den Händen, an einem gemeinsamen Abend"}'::jsonb, null, null, 19),
